from heapq import heappop, heappush

def heapify(tup, index, heap):
    left_index = 2*index + 1
    right_index = 2*index + 2
    smallest = index
    if left_index < len(tup) and tup[left_index] < tup[smallest]:
        smallest = left_index
    if right_index < len(tup) and tup[right_index] < tup[smallest]:
        smallest = right_index
    if smallest != index:
        tup[smallest], tup[index] = tup[index], tup[smallest]
        heap[smallest], heap[index] = heap[index], heap[smallest]
        heapify(tup, smallest, heap)

def extract_min(heap):
    min_value = heap[0]
    last_value = heap.pop()
    if heap:
        heap[0] = last_value
        heapify(heap, 0, heap)
    return min_value

def heap_operator(heap, index):
