        heap[0] += 1

        for i in range(9):
            heapify(heap, i, heap)
        operations -= 1

    if g % 2 == 1:
        min_sum -= heap.pop(0)
    return min_sum, [v for idx, v in enumerate(heap) if idx % 2 == g % 2]

