from math import gcd

def lcm(a, b):
    """Compute the least common multiple of two numbers."""
    return a * b // gcd(a, b)

def is_cool(desired_sequence):
    """Check if a given sequence is cool."""
    if len(desired_sequence) < 2:
        return 0
    n = len(desired_sequence)
    for i in range(n):
        if lcm(desired_sequence[i], desired_sequence[i - 1]) < desired_sequence[i]:
            return 0
    return max(desired_sequence) + 1 - lcm(*sorted(desired_sequence, reverse=True))

def steps_for_cool_sequence(a_sequence):
    """Determine the minimum number of steps to make a sequence cool."""
    b_sequence = sorted([c - a + 1 for a, c in zip(a_sequence, a_sequence[1:])])
    return is_cool(b_sequence) if b_sequence else len(a_sequence)

