        print("IMPOSSIBLE")
        return

    # Sort constraints to create in-order
    constraints.sort(key=lambda x: x[1])
    order = []
    parent = {}
    parent[0] = None

    def build_tree(node):
        if node in parent:
            return
        order.append(node)
        parent[node] = node

        for neighbor in constraints:
            if neighbor[1] == node:
                build_tree(neighbor[0])
            else:
                node_weights = list(parent.keys())[build_tree(neighbor[0])]
                if parent[node] in node_weights:
                    node_weights.remove(parent[node])

                build_tree(node_weights[0])
                parent[neighbor[0]] = parent[node]
                break

    if constraints[0][0] != 1:
        print("IMPOSSIBLE")
        return

    build_tree(1)

    if not constraints:
        print(" ".join(map(str, order)))
    else:
        print("IMPOSSIBLE")

