import sys

def find_burn_step(tree, query):
    def dfs(v):
        nonlocal prev_burn_step, leafs_info, n
        if tree[v][0] == -1:
            if leaf == v:  # Current vertex is a leaf
                return max(prev_burn_step, max(tree[v][1]) + 1)
            else:
                return max(leafs_info[v] + 1)
        else:
            lower_bound, upper_bound = dfs(tree[v][0]), dfs(tree[v][1])
            leafs_info[v] = max(lower_bound, upper_bound)
            return upper_bound  # Leaf will burn out first

    n = len(tree)  # get n from input
    leafs_info = [0] * n  # initialize leafs_info
    prev_burn_step = n + 1
    leaf = None
    # find the leaf for the initial query
    for i in range(n):
        if leafs_info[tree[i][0]] < leafs_info[tree[i][1]]:
            leaf = i
        else:
            if leaf == None:
                tree[i][1] = tree[i][0]  # duplicate arcs for dead-leaf case
            else:
                tree[i][0] = leaf
                if leafs_info[leaf] > leafs_info[tree[i][1]]:
                    leafs_info[i] = leafs_info[tree[i][1]]
                else:
                    leafs_info[i] = leafs_info[leaf]
    return dfs(leaf)

