def cool_pair(n, a):
    s = 0
    for x in a:
        if x < s:
            for i in range(s - x, s):
                if i < s and x - i < s:
                    return False
        else:
            for i in range(s - (x - s), s):
                if i < s - (x - s) and x - i < s:
                    return False
        s = x
    if s < 2:
        return False
    return True

def min_changes(n, a):
    changes = 0
    a.sort()
    for i in range(1, n+1):
        if not cool_pair(i, a):
            changes += i
            a[i-1] = a[i-2] + 1
    return changes

