    numbers = list(range(1, n + 1))

    while True:
        # Get the operation and the number a
        operation = input().strip()[0]
        a = int(input().strip())

        if operation == 'A':
            # Ask how many numbers are multiples of a
            multiples = count_multiples(numbers, a)
            print(f"{multiples}")
        elif operation == 'B':
            # Ask how many numbers are multiples of a and delete them
            if a <= len(numbers):
                multiples = count_multiples(numbers, a)
                remaining = delete_multiples(numbers, a)
                print(f"{multiples}")
            else:
                multiples = count_multiples(numbers, a)
                print(f"{multiples + 1}")
        elif operation == 'C':
            # We know the number x, print it
            print(f"{1}")
            return

def count_multiples(numbers, a):
    """Count how many numbers in the list are multiples of a"""
    return sum(1 for num in numbers if num % a == 0)

def delete_multiples(numbers, a):
    """Delete all numbers that are multiples of a from the list"""
    for i in range(len(numbers) - 1, -1, -1):
        if numbers[i] % a == 0:
            numbers.pop(i)
    return len(numbers)

